// A line arrives from the Arduino: if it's JSON, map it to Modbus registers
const hr = context.get('hr');
let line = String(msg.payload).trim();
if (!line.startsWith('{')) {          // '#' lines are diagnostics, not data
    if (line) node.log('Arduino: ' + line);
    return null;
}
let d;
try { d = JSON.parse(line); } catch (e) { return null; }
const i16 = (v) => Math.round(v) & 0xFFFF;
hr[0] = d.t === null ? 0 : i16(d.t * 10);   // temperature x10
hr[1] = d.h === null ? 0 : i16(d.h);        // humidity %
hr[2] = i16(d.light);                         // light %
hr[3] = d.obst;                             // obstacle 0/1
hr[4] = d.relay;                             // relay 0/1
hr[5] = d.mode === 'AUTO' ? 1 : 0;          // 1 = AUTO, 0 = MANUAL
hr[6] = i16(d.sp * 10);                     // setpoint x10
hr[7] = d.alarm;                           // alarm 0/1
hr[8] = d.run;                              // run 0/1
hr[9] = d.t === null ? 0 : 1;               // DHT11 sensor OK
hr[10] = (hr[10] + 1) & 0xFFFF;             // heartbeat counter
node.status({ fill: 'green', shape: 'dot', text: 'T=' + d.t + ' SP=' + d.sp + ' ' + d.mode });
return null;

