// Starts a Modbus TCP server (port 502, unit ID 1)
const hr = new Array(100).fill(0);
context.set('hr', hr);
const sendCmd = (cmd) => node.send({ payload: cmd });
const vector = {
  getHoldingRegister: (addr) => hr[addr] || 0,
  getInputRegister:   (addr) => hr[addr] || 0,
  setRegister: (addr, value) => {
    const v = value & 0xFFFF;
    const s = v > 32767 ? v - 65536 : v;
    if (addr === 20) sendCmd('SP=' + (s / 10).toFixed(1));
    else if (addr === 21 && v === 1) sendCmd('MODE=AUTO');
    else if (addr === 21 && v === 2) sendCmd('MODE=MANUAL');
    else if (addr === 22 && v === 1) sendCmd('RELAY=1');
    else if (addr === 22 && v === 2) sendCmd('RELAY=0');
    else if (addr === 23 && v === 1) sendCmd('RESET');
    else if (addr === 24 && v === 1) sendCmd('MUTE');
    else if (addr === 25 && v === 1) sendCmd('RUN=1');
    else if (addr === 25 && v === 2) sendCmd('RUN=0');
    else if (addr === 26 && v === 1) sendCmd('TEST');
    hr[addr] = 0;               // command registers are pulses: reset to 0 after use
  },
  getCoil: () => false,
  setCoil: () => {}
};
const server = new ModbusRTU.ServerTCP(vector, { host: '0.0.0.0', port: 502, unitID: 1 });
server.on('socketError', (e) => node.warn('Modbus: ' + e.message));
server.on('initialized', () => node.status({ fill: 'green', shape: 'dot', text: 'Modbus TCP :502' }));
context.set('server', server);
